#include <stdio.h>
#include <ctype.h>

#define FILE_NAME "upper.txt"

int main(void)
{
    FILE *fp;
    int ch;

    /* 从键盘读入，遇 ! 结束，小写转大写后写入文件（! 本身不写入） */
    fp = fopen(FILE_NAME, "w");
    if (fp == NULL)
        return 1;
    while ((ch = getchar()) != EOF && ch != '!')
        fputc(toupper(ch), fp);
    fclose(fp);

    /* 再把文件内容读出并原样显示，不额外添加换行 */
    fp = fopen(FILE_NAME, "r");
    if (fp == NULL)
        return 1;
    while ((ch = fgetc(fp)) != EOF)
        putchar(ch);
    fclose(fp);

    return 0;
}

